package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaHaDraft6 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_sharri_ma_amiltu" to DuaText("Ku Tsare Daga Sharrin Ayyukana", "Ya Allah ina neman tsarinka daga sharrin abin da na aikata, da sharrin abin da ban aikata ba.", "Addu'ar Annabi ﷺ, in ji Aisha (RA).", "Kariya daga sakamakon abin da aka yi da abin da aka bari."),
        "dua_jahdil_bala" to DuaText("Gudun Hijira Daga Matsanancin Gwaji", "Ya Allah ina neman tsarinka daga fitintinu mai tsanani, da mugun nufi, da mugun nufi da gorin makiya.", "Ku mafaka daga fitintinu masu tsanani da hamdala na makiya.", "Annabi ﷺ ya nemi tsari daga wadannan abubuwa guda hudu."),
        "dua_fitnat_ghina_faqr" to DuaText("Gudun Hijira daga Fitinun Dukiya da Talauci", "Ya Allah ina neman tsarinka daga kasala da tsufa, da zunubi da bashi, da fitinar kabari, da fitinar wuta, da sharrin fitinar dukiya, da fitinar talauci.", "Ku gudu daga fitinun kabari, wuta, dukiya da talauci (bangaren dua).", "Cikakken addu'ar neman tsari daga Annabi ﷺ."),
        "dua_kufr_faqr" to DuaText("Ku gujewa Kafirci da Talauci", "Ya Allah ina neman tsarinka daga kafirci da talauci, kuma ina neman tsarinka daga azabar kabari. Babu abin bautawa face Kai.", "Sau uku safe da yamma.", "Abu Bakrah (RA) yaji Annabi ﷺ yana fadin haka."),
        "dua_sharri_sami" to DuaText("Ku gujewa Sharrin Hankalina", "Ya Allah ina neman tsarinka daga sharrin ji na, da sharrin ganina, da sharrin harshe na, da sharrin zuciyata, da sharrin sha'awata.", "An karantar da Shakal bin Humayd (RA).", "Adua don kare gabobin jiki da kai daga zunubi."),
        "dua_hadm_gharaq" to DuaText("Gudun Hijira daga Mutuwar Kwatsam da Hatsari", "Ya Allah ina neman tsarinka da nitsewa (da gini), da fadowa daga tsauni, da nutsewa, da qonawa, da tsufa; daga shaiɗan ya batar da ni a lokacin mutuwa, da in mutu, alhali kuwa ina gudu daga tafarkinka, kuma da in mutu da azaba.", "Gudun hijira daga hatsarori da mummunar mutuwa.", "Addu'ar tsari daga Annabi ﷺ."),
        "dua_ju_khiyanah" to DuaText("Gudun Hijira Daga Yunwa da Cin Amana", "Ya Allah ina neman tsarinka daga yunwa, domin shi mugun sahabi ne, kuma ina neman tsarinka daga cin amana, domin shi mugunyar amana ce.", "Ku gudu daga yunwa da cin amana.", "Addu'ar tsari daga Annabi ﷺ."),
        "dua_huda_tuqa" to DuaText("Shiriya, Taqawa, Tsafta da Wadatarsa", "Ya Allah ina rokonka shiriya da takawa da tsafta da wadatar kai.", "A takaice, cikakkiyar addu'ar Annabi ﷺ.", "Ni'ima guda hudu na addini da na duniya."),
        "dua_aslih_li_dini" to DuaText("Ka Gyara Addinina, Duniya Da Lahira", "Ya Allah ka gyara min addinina, wanda shi ne majibincin dukkan al'amura na; Ka kyautata rayuwata ta duniya, wadda take a cikinta take; Kuma ka daidaita Lãhirata, zuwa gare ta zan mayar. Ka sanya rayuwa ta ƙaru a gare ni cikin kowane alheri, kuma Ka sanya mutuwa ta zama mafita a gare ni daga kowane sharri.", "Mai gyara addini, duniya da lahira - duka ukun.", "Cikakken Addu'ar Annabi ﷺ."),
        "dua_musarrifal_qulub" to DuaText("Ka Juya Zukatanmu Zuwa Biyayyar Ka", "Ya Allah mai juyar da zukata, ka karkatar da zukatanmu zuwa ga biyayyarka.", "Addu'a don tabbatar da zuciya a cikin biyayya.", "Zukatan dukkan mutane suna tsakanin yatsu biyu na Mai rahama."),
        "dua_jannah_nar" to DuaText("Neman Aljannah, mafaka daga Wuta", "Ya Allah ina rokonka Aljannah, kuma ina neman tsarinka daga wuta.", "Bayan tashahud ko a kowane lokaci.", "Annabi ﷺ ya ce: “Addu’o’inmu ma sun ta’allaka ne a kan wannan."),
        "dua_khayri_kullih" to DuaText("Duk Mai Kyau, Yanzu da Daga baya", "Ya Allah ina rokonka da alheri – na gaugawa da wanda aka jinkirtar, da abin da na sani da wanda ban sani ba – kuma ina neman tsarinka daga dukkan sharri – na gaugawa da jinkiri, abin da na sani da wanda ban sani ba. Ya Allah ina rokonka Aljannah da duk wata magana da aiki da za su kusance ni zuwa gare ta, kuma ina neman tsarinka daga wuta da duk wata magana da aiki na kusantarta.", "Annabi ﷺ ya koyar da wannan cikakkiyar dua ga Aisha (RA) (bangaren dua).", "Adua mai tara duk wani alheri."),
        "dua_ihdini_saddidni" to DuaText("Ka Yi Mini Ka Tsaya Ni Madaidaici", "Ya Allah ka shiryar dani, ka datar da ni akan tafarki madaidaici.", "Annabi ﷺ ya koya wa Ali (RA).", "Ka yi la'akari da shiriya kamar yadda ake shiryarwa a kan hanya, kuma sadad kamar madaidaiciyar kibiya."),
        "dua_hubbaka" to DuaText("Neman Soyayyar Allah", "Ya Allah ina rokonka soyayyar ka, son masu sonka, da ayyukan da suke kawo ni zuwa ga sonka. Ya Allah ka sanya soyayyar ka ta fi soyuwa a gareni fiye da ni da iyalaina da ruwan sanyi.", "Addu'ar Dawud (AS) ta Annabi ﷺ.", "Son Allah shine mafi girman arziki."),
        "dua_filal_khayrat" to DuaText("Yin Kyau da Barin Mummuna", "Ya Allah ina rokonka da ka bani ikon aikata aikin kwarai, da barin munanan ayyuka da son miskinai, ka gafarta mini, ka yi mani rahama. Kuma idan Ka yi nufin fitina ga mutãne, to, ka kama ni, bã da an fitine ni ba. Ina rokonka soyayyar ka, soyayyar masu son ka, da son ayyukan da suke kusantar da ni zuwa ga kaunar ka.", "Allah ya horema Annabi ﷺ wannan addu'ar a mafarki.", "Annabi ﷺ ya ce: gaskiya ne, don haka ku koya kuma ku karantar da shi."),
        "dua_bi_ilmikal_ghayb" to DuaText("Bari Na Rayuwa Alhali Rayuwa Tana Da Kyau", "Ya Allah, bisa ga sanin gaibi da ikonka a kan halitta, ka raya ni matukar ka san rayuwa ta fi alheri a gare ni, kuma ka dauke ni alhalin ka san mutuwa ce ta fi alheri a gare ni. Ya Allah ina rokonka da tsoronka a boye da bayyane, da kalmar gaskiya cikin wadatar zuci da fushi, da daidaitawa cikin talauci da dukiya.", "Addu'ar Ammar bn Yasir (RA).", "Annabi ﷺ yayi wannan addu'ar a cikin addu'a."),
        "dua_ism_azam_mannan" to DuaText("Ism-e-Azam: Al-Mannan", "Ya Allah ina rokonka, lalle ne godiya ta tabbata gareka; babu wani abin bautãwa fãce Kai, Mai ni'ima, Mai ƙãga halittar sammai da ƙasa. Ya Ma'abucin Girma da Girmamawa, Ya Rayayye, Ya Ubangiji!", "Annabi ﷺ yace wannan mutumin yayi addu'a da Sunan Allah Mafi Girma.", "Ana amsa addu'ar da aka yi da wannan Suna."),
        "dua_ism_azam_ahad_samad" to DuaText("Ism-e-Azam: Al-Ahad As-Samad", "Ya Allah ina rokonka, domin na shaida kai ne Allah; babu wani abin bautãwa fãce Kai, Makaɗaici, Mawadãci, wanda bã Ya haifuwa, kuma bã a haife shi, kuma bãbu wani misãli a gare Shi.", "Annabi ﷺ yace wannan mutumin ya tambayi Allah da sunansa mafi girma.", "Idan aka tambaye shi sai ya bayar; idan aka kira shi, sai ya amsa."),
        "dua_thabbitni_hadiyan" to DuaText("Ka Sanya Ni Dage, Mai Shiryuwa Da Jagora", "Ya Allah ka tabbatar da ni, kuma ka sanya ni mai shiryarwa da shiryuwa.", "Annabi ﷺ yayi wannan addu'ar ga Jarir (RA) (da kanka kace 'thabbitni').", "Asalin dua na Jarir (RA) yana amfani da kalmomin 'thabbit-hu'."),
        "dua_rabbighfir_tub_alayya" to DuaText("Ka Gafarta Mani Ka Karbi Tuba Na", "Ubangijina Ka gafarta mini, kuma ka karbi tuba ta. Lalle Kai ne Mai karɓar tũba, Mai jin ƙai.", "Sau dari a zaune guda - aikin Annabi ﷺ.", "Sahabbai sun kirga Annabi ﷺ yana cewa sau dari a zama daya."),
        "dua_rafiq_ala" to DuaText("Addu'ar Mutumin da ya mutu", "Ya Allah Ka Gafarta Mani, Ka Yi Mani Rahma, Ka Hada Ni Da Mafificin Sahabi.", "Addu'ar karshe ta Annabi ﷺ - don mara lafiya ya fada wa kansa.", "Annabi ﷺ yayi wannan addu'ar a lokacin wafatinsa."),
        "dua_la_bas_tahur" to DuaText("Ta'aziyyar Marasa Lafiya: Tsarkakewa", "Babu cutarwa; tsarki ne (daga zunubai), in Allah Ya so.", "Don ta'aziyya mara lafiya lokacin ziyara.", "Annabi ﷺ ya fadi haka lokacin da ya ziyarci marasa lafiya."),
        "dua_talqeen" to DuaText("Talqiin don Matattu", "Babu abin bautawa da gaskiya sai Allah.", "Karanta kalimah kusa da mai mutuwa (kada ku tilasta musu su faɗi).", "Duk wanda kalmar karshensa ta kasance 'La'ilaha illallah' zai shiga Aljanna (Abu Dawud 3116)."),
        "dua_ahyini_ma_kanat" to DuaText("Maimakon Fatan Mutuwa", "Ya Allah ka raya ni matukar rayuwa ta zame mani, kuma ka dauke ni lokacin da mutuwa ta fi min.", "Maimakon fatan mutuwa cikin wahala.", "Annabi ﷺ ya hana fata mutuwa ya koyar da haka maimakon haka."),
        "dua_for_one_i_cursed" to DuaText("Ga Wani Na Rauni Da Kalamai", "Ya Allah duk wani Muminin da na zage shi, ka sanya hakan ya zama hanyar kusanci gare Ka a gare shi ranar kiyama.", "Ga wanda ka yi masa mugun magana cikin fushi.", "Addu'ar Annabi ﷺ."),
        "dua_praising_someone" to DuaText("Lokacin Yabon Wani", "Ni ina ganin haka da wane, kuma Allah ne Mai hisabi, kuma ba na baiwa kowa tsarkin sa a wurin Allah.", "Lokacin yabon wani, maimakon wuce gona da iri.", "Annabi ﷺ ya koyar da wannan ladubban yabo."),
        "dua_being_praised" to DuaText("Lokacin Ana Yabo", "Ya Allah kada ka yi min hisabi a kan abin da suke fada, kuma ka gafarta mini abin da ba su sani ba.", "Da jin kai yabo - aikin Sahabi (RA).", "Hanyar gujewa girman kai idan ana yabo."),
        "dua_non_muslim_sneezes" to DuaText("Lokacin da Wanda ba Musulmi ba yayi atishawa", "Allah yayi muku jagora ya daidaita al'amuran ku.", "Idan wanda ba musulmi ba ya yi atishawa ya ce Alhamdulillah.", "Yahudawa sukan yi atishawa kusa da Annabi ﷺ suna fatan ya ce 'Yarhamukallah', sai ya fadi haka."),
        "dua_reply_ahl_kitab_salam" to DuaText("Amsa zuwa ga Salama Ahlul Kitabi", "Kuma akan ku.", "Idan Ahlul Kitabi suka yi sallama.", "Wa'azin Annabi ﷺ."),
        "dua_fasting_invited" to DuaText("Lokacin Gayyata Lokacin Azumi", "Ina azumi.", "Lokacin da aka gayyace ku lokacin azumi, ko kuma lokacin da wani ya yi jayayya da ku.", "Idan mai azumi ya karbi gayyata, sai ya yi wa mai masaukin baki addu’a."),
        "dua_for_who_gave_drink" to DuaText("Ga Duk Wanda Ya Azurta Ni", "Ya Allah ka ciyar da wanda ya ciyar dani, ka shayar da wanda ya shayar da ni.", "Domin wanda ya ba ku abinci ko abin sha.", "Annabi ﷺ yayi wannan addu'ar ga al-Miqdad (RA)."),
        "dua_eid_greeting" to DuaText("Gaisuwar Idi", "Allah ya karba mana (ayyuka nagari) daga gare mu da ku.", "Ga junanmu a ranar Idi - ayyukan Sahabbai masu daraja (RA).", "Sahabbai sun fadi haka ne a lokacin da suka hadu a Idi."),
        "dua_wedding_night" to DuaText("Ga Amarya Bayan Nikah", "Ya Allah ina rokonka alherinta da nagartar dabi'ar da ka halicce ta da ita, kuma ina neman tsarinka daga sharrinta da sharrin dabi'ar da ka halicce ta da ita.", "Bayan nikah, dora hannu akan goshin matar.", "Koyarwar Annabi ﷺ - albarka a cikin aure."),
        "dua_istisqa_ibadak" to DuaText("Shayar da Bayinka da Dabbobinka", "Ya Allah ka shayar da bayinka da dabbobinka, ka yada rahamarka, ka raya matacciyar kasarka.", "Neman ruwan sama (istisqa).", "Annabi ﷺ yayi wannan addu'ar domin ruwan sama."),
        "dua_seeing_clouds" to DuaText("Ganin Duhun Gizagizai", "Ya Allah ina neman tsarinka daga sharrinta.", "A kan ganin duhun gajimare a sararin sama; idan aka yi ruwa a ce Allahumma sayyiban nafi'a.", "A kan ganin gajimare, Annabi ﷺ zai bar abin da yake yi ya yi wannan dua."),
        "dua_jamarat" to DuaText("Jifan Jamarat", "Allah shi ne mafi girma.", "Da kowace tsakuwa jifa.", "Annabi ﷺ ya yi takbir da kowace tsakuwa, sannan bayan jamra ta farko da ta biyu ta fuskanci alkibla kuma ta yi doguwar addu'a."),
        "dua_rabbi_ainni" to DuaText("Ubangijina, Ka Taimake Ni, Kada Ka Taimaka Ni", "Ya Ubangijina, Ka taimake ni, kada ka taimaki wani a kaina, Ka ba ni nasara, kuma kada ka ba wa wasu nasara a kaina, Ka yi mini tsari, kuma kada ka yi mini makirci, Ka shiryar da ni, kuma Ka sauwake mani shiriya, kuma Ka taimake ni a kan wanda ya zalunce ni.", "Cikakken Addu'ar Annabi ﷺ (Bude part).", "Addu'ar da ke tattara kowane taimako a addini da duniya."),
        "dua_ati_nafsi_taqwaha" to DuaText("Ka Ba Raina Ta Takawa", "Ya Allah ka baiwa raina takawa, ka tsarkake ta, domin kai ne mafificin tsarkake ta. Kai ne Majibincinta kuma Shugabanta.", "Domin gyarawa da tsarkake kai.", "Annabi ﷺ ya kasance yana yin wannan dua."),
        "dua_iqsim_lana_khashyatik" to DuaText("Ka Bamu Irin Wannan Tsoron Ka", "Ya Allah ka ba mu isashen tsoronka ka shiga tsakaninmu da saba maka, isashen biyayyar da zai kaimu Aljannarka, da kuma isashen yakini ka sauwake mana masifun duniya. Muji dadin jinmu da ganinmu da karfinmu matukar Ka raya mu, kuma ka sanya su fi karfinmu. Ka dau fansa a kan wadanda suka zalunce mu, ka taimake mu a kan makiyanmu, kada ka bari bala'in mu ya kasance a cikin addininmu, kada ka sanya duniyar nan babbar damuwa a gare mu ko iyakar iliminmu, kuma kada ka sanya wanda ba zai tausaya mana ba.", "Lokacin da aka tashi daga taro - Annabi ﷺ da wuya ya tashi ba tare da yin wannan addu'ar ba.", "Cikakken addu'a don amfanin addini, duniya da lahira."),
        "dua_infani_bima_allamtani" to DuaText("Ka Amfaneni Da Abinda Ka Koya Mani", "Ya Allah ka amfaneni da abinda ka karantar dani, ka sanar dani abinda zai amfaneni, ka karamana ilimi.", "Yayin neman ilimi ko kafin karatu.", "Addu'a don ilimi mai amfani da aiki da shi."),
    )
}
